        readonly 'integrationsCatalog.entry.rootly.details': 'Connect Rootly so the agent can look up incidents and who is on call, update incidents and help with retrospectives.';
        readonly 'integrationsCatalog.entry.groundcover.details': 'Connect groundcover so the agent can query logs, traces and metrics collected from your Kubernetes clusters.';
        readonly 'integrationsCatalog.entry.signoz.details': 'Connect SigNoz Cloud so the agent can query traces, logs and metrics and look at alerts and dashboards. Comes with SigNoz skills for investigating alerts, writing queries and building dashboards.';
        readonly 'integrationsCatalog.entry.openobserve.details': 'Connect OpenObserve Cloud so the agent can search logs, metrics and traces with SQL and PromQL.';
        readonly 'integrationsCatalog.entry.logrocket.details': 'Connect LogRocket so the agent can look into user sessions, errors and performance issues in your web and mobile apps.';
        readonly 'integrationsCatalog.entry.uptimerobot.details': 'Connect UptimeRobot so the agent can list monitors, read uptime and incidents and manage status pages. Comes with UptimeRobot skills for SLA reports and a quick health summary.';
        readonly 'integrationsCatalog.entry.onlineornot.details': 'Connect OnlineOrNot so the agent can look at uptime and browser checks, scheduled job heartbeats and status pages.';
        readonly 'integrationsCatalog.entry.openstatus.details': 'Connect OpenStatus so the agent can read monitor results from several regions and post incidents and maintenance to status pages.';
        readonly 'integrationsCatalog.entry.hyperping.details': 'Connect Hyperping with a project API key so the agent can read monitors, outages and their timelines, uptime and on-call schedules.';
        readonly 'integrationsCatalog.entry.oneuptime.details': 'Connect OneUptime with a project API key so the agent can work with monitors, incidents, alerts, status pages and telemetry. A read-only key is enough for looking around.';
        readonly 'integrationsCatalog.entry.firecrawl.details': 'Connect Firecrawl so the agent can search the web, scrape pages into clean Markdown, crawl sites and parse documents. Comes with Firecrawl skills for cited deep-research reports, literature reviews, competitor tracking and SEO audits.';
        readonly 'integrationsCatalog.entry.tavily.details': 'Connect Tavily so the agent can search the web, extract content from pages and run research on live data.';
        readonly 'integrationsCatalog.entry.jina.details': 'Give the agent Jina AI tools for reading web pages and PDFs, web and arXiv search, screenshots and reranking. Works without a key within the free limit; add an API key for more.';
