        readonly 'integrationsCatalog.entry.browserbase.details': 'Connect Browserbase with an API key so the agent can open a cloud browser, navigate, act on pages and extract data.';
        readonly 'integrationsCatalog.entry.browser-use.details': 'Connect Browser Use with an API key so the agent can hand a task to a cloud browser agent and follow its progress.';
