        readonly 'integrationsCatalog.entry.braintrust.details': 'Connect Braintrust so the agent can read production traces, work with datasets and run and compare evaluations.';
        readonly 'integrationsCatalog.entry.logfire.details': 'Connect Logfire so the agent can query traces and logs with SQL and look at dashboards and alerts. This entry uses the US region. Comes with the Logfire query skill.';
        readonly 'integrationsCatalog.entry.chroma-package-search.details': 'Connect Chroma Package Search with an API key so the agent can grep and read the source of npm, PyPI, crates and other packages your code depends on.';
        readonly 'integrationsCatalog.entry.mem0.details': 'Connect Mem0 so the agent can store, search and update memories that carry over between sessions.';
        readonly 'integrationsCatalog.entry.attio.details': 'Connect Attio so the agent can look up companies and people, log notes from calls, track deals and create follow-up tasks.';
