        readonly 'integrationsCatalog.entry.day-ai.details': 'Connect Day AI so the agent can draw on the CRM records Day AI builds from your emails, chats and meetings.';
        readonly 'integrationsCatalog.entry.lightfield.details': 'Connect Lightfield so the agent can read customer records and interactions it has captured and help with sales follow-ups.';
        readonly 'integrationsCatalog.entry.plain.details': 'Connect Plain so the agent can read and reply to support threads, look up customers and work with help center content.';
        readonly 'integrationsCatalog.entry.pylon.details': 'Connect Pylon so the agent can search, update and resolve customer issues in your support queue.';
        readonly 'integrationsCatalog.entry.unthread.details': 'Connect Unthread so the agent can search support conversations, watch SLAs and analyze helpdesk metrics.';
        readonly 'integrationsCatalog.entry.intercom.details': 'Connect Intercom so the agent can search customer conversations, tickets and user data, for example to spot bugs or find feedback. Comes with Intercom skills for analyzing conversations and building a full customer view.';
        readonly 'integrationsCatalog.entry.superhuman.details': 'Connect Superhuman Mail so the agent can search your inbox, draft replies in your voice, set reminders and schedule meetings. Comes with Superhuman skills for a morning briefing, an end-of-day wrap-up and scheduling meetings.';
        readonly 'integrationsCatalog.entry.ramp.details': 'Connect Ramp for read-only access to transactions, reimbursements, bills, cards and vendors, so the agent can analyze company spend.';
        readonly 'integrationsCatalog.entry.brex.details': 'Connect Brex so the agent can query expenses, check policy and compliance and answer spend questions, within your Brex permissions.';
        readonly 'integrationsCatalog.entry.mercury.details': 'Connect Mercury so the agent can check balances, search and chart transactions and download statements.';
        readonly 'integrationsCatalog.entry.gusto.details': 'Connect Gusto so the agent can answer questions about payroll and your team and build reports from them.';
        readonly 'integrationsCatalog.entry.remote.details': 'Connect Remote so the agent can look up employees, payroll, time off and expenses for your global team. Comes with the Remote skill for payroll and payslips.';
        readonly 'integrationsCatalog.entry.ashby.details': 'Connect Ashby so the agent can look up candidates and jobs, review interview feedback and read recruiting analytics.';
        readonly 'integrationsCatalog.entry.pandadoc.details': 'Connect PandaDoc so the agent can create documents from templates, send them for signature and track their status.';
        readonly 'integrationsCatalog.entry.make.details': 'Connect Make so the agent can run scenarios and view or change them along with their connections, webhooks and data stores. Comes with Make skills for exploring, building and running scenarios.';
        readonly 'integrationsCatalog.entry.ifttt.details': 'Connect IFTTT so the agent can run actions across more than a thousand services and create or update Applets.';
        readonly 'integrationsCatalog.entry.windmill.details': 'Connect Windmill so the agent can run your scripts and flows and work with the resources in your workspace.';
        readonly 'integrationsCatalog.entry.resource-monitor.description': 'Watch CPU and memory of your machine, OpenChamber and dev servers';
        readonly 'integrationsCatalog.entry.resource-monitor.details': 'Install the Resource Monitor extension for a panel with live CPU and memory of your machine, OpenChamber, OpenCode and the dev servers they started, and a Stop button for runaway commands. Works on web and desktop.';
