        readonly 'integrationsCatalog.entry.surveymonkey.details': 'Conecta SurveyMonkey para que el agente redacte encuestas, lea respuestas y saque tendencias de los resultados.';
        readonly 'integrationsCatalog.entry.craft.details': 'Conecta Craft para que el agente cree y edite documentos, guarde notas y tareas, y las organice en carpetas y espacios.';
