        readonly 'integrationsCatalog.entry.surveymonkey.details': '连接 SurveyMonkey 后，智能体可以起草问卷、读取回复，并从结果中找出趋势。';
        readonly 'integrationsCatalog.entry.craft.details': '连接 Craft 后，智能体可以创建和编辑文档、记录笔记和待办，并把它们整理到文件夹和空间中。';
        readonly 'integrationsCatalog.entry.evernote.details': '连接 Evernote 后，智能体可以搜索你的笔记本、阅读和创建笔记，并整理标签和任务。';
        readonly 'integrationsCatalog.entry.mem.details': '连接 Mem 后，智能体可以在你的笔记中搜索上下文、记录新想法并更新持续维护的文档。';
        readonly 'integrationsCatalog.entry.readwise.details': '连接 Readwise 后，智能体可以搜索你的高亮和保存到 Reader 的所有内容，并整理资料库中的文档。';
        readonly 'integrationsCatalog.entry.guru.details': '连接 Guru 后，智能体会依据你经过验证的公司知识作答，权限与你在 Guru 中的相同。';
        readonly 'integrationsCatalog.entry.egnyte.details': '连接 Egnyte 后，智能体可以搜索、阅读和分析公司文件，并遵循 Egnyte 的权限和审计日志。';
        readonly 'integrationsCatalog.entry.fireflies.details': '连接 Fireflies 后，智能体可以查找会议、阅读转录和摘要，并提取决定和待办事项。';
        readonly 'integrationsCatalog.entry.fathom.details': '连接 Fathom 后，智能体可以阅读通话的摘要、转录和待办事项，并基于实际说过的内容继续工作。';
        readonly 'integrationsCatalog.entry.otter.details': '连接 Otter 后，智能体可以按日期、人员或主题查找会议，并阅读其转录和摘要。';
        readonly 'integrationsCatalog.entry.read-ai.details': '连接 Read AI 后，智能体可以阅读会议摘要、转录、待办事项和关键问题。';
        readonly 'integrationsCatalog.entry.circleback.details': '连接 Circleback 后，智能体可以搜索会议笔记和转录，以及相关的日历事件、人员和公司。';
        readonly 'integrationsCatalog.entry.fellow.details': '连接 Fellow 后，智能体可以搜索转录、从会议摘要中提取洞察并跟进待办事项。';
        readonly 'integrationsCatalog.entry.krisp.details': '连接 Krisp 后，智能体可以查阅你的会议历史、过往决定和待办事项。';
        readonly 'integrationsCatalog.entry.deepwiki.details': '为智能体提供 DeepWiki：为公开仓库生成的文档，以及基于其代码的回答。无需账户。';
        readonly 'integrationsCatalog.entry.sourcegraph.details': '连接 Sourcegraph 后，智能体可以在你的所有仓库中搜索代码、跟随定义和引用，并阅读找到的文件。';
        readonly 'integrationsCatalog.entry.jam.details': '连接 Jam 后，聊天中的 Jam 链接会把整段录制交给智能体：视频、控制台、网络请求和日志，无需重新输入复现步骤。';
        readonly 'integrationsCatalog.entry.statsig.details': '连接 Statsig 后，智能体可以创建和修改功能门控、动态配置和实验，并读取其结果。附带 Statsig 技能，用于处理门控、实验和配置。';
        readonly 'integrationsCatalog.entry.devcycle.details': '连接 DevCycle 后，智能体可以创建功能开关、编辑定向规则和变量，并检查开关的求值结果。';
        readonly 'integrationsCatalog.entry.flagsmith.details': '连接 Flagsmith 后，智能体可以切换功能开关、编辑远程配置，并跨环境管理分群。';
        readonly 'integrationsCatalog.entry.clerk.details': '连接 Clerk 后，智能体可以获得登录、会话、路由保护和组织方面的最新 SDK 代码片段和用法。';
        readonly 'integrationsCatalog.entry.workos.details': '连接 WorkOS 后，智能体可以处理你的环境、组织、用户、SSO 连接和目录同步。';
        readonly 'integrationsCatalog.entry.stytch.details': '连接 Stytch 后，智能体可以管理你的项目：重定向 URL、邮件模板、公共令牌等。';
        readonly 'integrationsCatalog.entry.descope.details': '连接 Descope 后，智能体可以处理你的项目：用户、租户、角色和认证设置。';
        readonly 'integrationsCatalog.entry.buf.details': '连接 Buf 后，智能体可以在 Buf Schema Registry 中查找模块、Protobuf 和 gRPC 定义及其版本。';
        readonly 'integrationsCatalog.entry.apollo-graphos.details': '为智能体提供 Apollo 文档搜索、Connectors 规范，以及用于模式、检查和发布的 GraphOS 工具。文档搜索无需账户。';
        readonly 'integrationsCatalog.entry.scalar.details': '为智能体提供 Scalar 文档搜索，涵盖其 API 参考、API 客户端和注册表。无需账户。';
        readonly 'integrationsCatalog.entry.redocly.details': '为智能体提供 Redocly 文档，涵盖 API 文档、代码检查和开发者门户。无需账户。';
        readonly 'integrationsCatalog.entry.swaggerhub.details': '连接 SwaggerHub 后，智能体可以查找 API 定义、阅读和更新 OpenAPI 规范并管理其版本。';
        readonly 'integrationsCatalog.entry.mintlify.details': '连接 Mintlify 后，智能体可以搜索和更新你的文档站点，并查看它们的使用情况。';
        readonly 'integrationsCatalog.entry.cloudinary.details': '连接 Cloudinary 后，智能体可以上传图片和视频、搜索和标记资源，并应用转换。';
        readonly 'integrationsCatalog.entry.mux.details': '连接 Mux 后，智能体可以上传和查看视频资源、管理直播并读取播放分析。';
        readonly 'integrationsCatalog.entry.knock.details': '连接 Knock 后，智能体可以创建和编辑工作流、模板和渠道，并查看已发送的内容。';
        readonly 'integrationsCatalog.entry.novu.details': '连接 Novu 后，智能体可以管理工作流、订阅者和应用内收件箱通知，并跨渠道触发它们。';
        readonly 'integrationsCatalog.entry.courier.details': '使用 API 密钥连接 Courier 后，智能体可以创建模板、发送测试通知、运行旅程并读取投递日志。附带 Courier 的通知构建技能。';
        readonly 'integrationsCatalog.entry.lucid.details': '连接 Lucid 后，智能体可以根据对话生成 Lucidchart 图表，并搜索、打开和共享你已有的图表。';
        readonly 'integrationsCatalog.entry.whimsical.details': '连接 Whimsical 后，智能体可以创建和更新白板：流程图、思维导图、线框图和文档。';
        readonly 'integrationsCatalog.entry.mermaid-chart.details': '为智能体提供 Mermaid 校验器和渲染器，让它写出的图表经过检查并绘制为 SVG。无需账户。';
        readonly 'integrationsCatalog.entry.tldraw.details': '为智能体提供 tldraw 画布，用于绘制流程图、架构图、线框图和思维导图。无需账户。';
        readonly 'integrationsCatalog.entry.magic-patterns.details': '连接 Magic Patterns 后，智能体可以和你一起创建并完善前端设计和原型。';
